def document(path):
    """测试编辑受信本地规则文件；不把测试 loader 当生产 YAML 解析器。"""
    return json.loads("\n".join(line for line in path.read_text().splitlines() if not line.startswith("#")))


@pytest.mark.parametrize("mutation", ["missing_rule", "duplicate_number", "enum_added", "effect_in_violation", "unknown_field", "selector_type", "unsafe_selector", "empty_clause", "oversize", "duplicate_json_key", "general_yaml", "byte_tamper"])
def test_rule_loader_fails_closed_without_echo(tmp_path: Path, policy, mutation):
    """坏策略、通用 YAML 特性和同版本字节篡改均不被默默接受。"""
    root = Path(__file__).resolve().parents[2] / "contracts/decisions"
    for name in ("fetch-actions.v1.yaml", "fetch-violations.v1.yaml"):
        (tmp_path / name).write_bytes((root / name).read_bytes())
    path = tmp_path / "fetch-actions.v1.yaml"
    data = document(path)
    if mutation == "missing_rule": data["rules"].pop()
    elif mutation == "duplicate_number": data["rules"][1]["number"] = 1
    elif mutation == "enum_added": data["enum_domains"]["status"].append("new-status")
    elif mutation == "effect_in_violation":
        path = tmp_path / "fetch-violations.v1.yaml"
        data = document(path)
        data["rules"][0]["effect"] = dict(next_action="halt", job_target="paused", checkpoint_policy="none", follow_up="manual")
    elif mutation == "unknown_field": data["secret-fixture"] = "must-not-echo"
    elif mutation == "selector_type": data["rules"][0]["when"][0]["has_continuation"] = [1]
    elif mutation == "unsafe_selector": data["rules"][0]["when"][0]["__class__"] = ["must-not-echo"]
    elif mutation == "empty_clause": data["rules"][0]["when"] = [{}]
    if mutation == "oversize": path.write_bytes(b" " * 65537)
    elif mutation == "duplicate_json_key": path.write_text('{"kind":"must-not-echo","kind":"actions"}')
    elif mutation == "general_yaml": path.write_text('!!python/object/apply:os.system ["must-not-echo"]')
    elif mutation == "byte_tamper": path.write_text(path.read_text() + "\n")
    else: path.write_text(json.dumps(data))
    with pytest.raises(DecisionPolicyError) as error:
        load_decision_policy(tmp_path, expected_lock=policy.lock if mutation == "byte_tamper" else None)
    assert "must-not-echo" not in str(error.value)


