def test_profile_reachable_context_and_small_explicit_shard(policy):
    """新轮廓拆分 present/failed；唯一排除必须由正式模型实际拒绝。"""
    assert prod(map(len, DIMENSIONS.values())) == 3686400
    assert len(OUTCOME_CASES) == 10
    recorded = json.loads((Path(__file__).resolve().parents[2] / "docs/validation/m0-05a-fetch-decisions.json").read_text())
    assert recorded["exhaustive"] is True and recorded["policy_lock"] == policy.lock.model_dump()
    assert recorded["measurement"]["raw_total"] == 3686400
    assert recorded["measurement"]["excluded_single_query"] == 921600
    assert recorded["measurement"]["evaluated"] == 2764800
    with pytest.raises(ValidationError):
        inputs(single=True, request="query_or_stream")
    scan = scan_decisions(policy, shard_index=1, shard_count=997)
    assert recorded["measurement"]["profile_digest"] == scan.profile_digest
    assert scan.selected == len(range(1, scan.raw_total, 997))
    assert scan.selected == scan.evaluated + scan.excluded_single_query
    assert scan.evaluated == scan.valid + scan.violation and scan.valid > 0
    for ordinal in (0, 1, 12345, 3686399):
        values = values_at_ordinal(ordinal)
        assert len(values) == len(DIMENSIONS)
    with pytest.raises(ValueError): values_at_ordinal(-1)
    for index, count in ((True, 2), (0, 0), (2, 2), (0, 3686401)):
        with pytest.raises(ValueError): scan_decisions(policy, shard_index=index, shard_count=count)


def test_cli_records_all_codes_and_marks_shards(tmp_path: Path, monkeypatch, capsys):
    """压缩记录逐条保留所有命中，显式分片摘要不能冒充全量。"""
    monkeypatch.setattr("sys.argv", ["verify", "--shard-index", "1", "--shard-count", "997", "--output-dir", str(tmp_path)])
    main()
    summary = json.loads(capsys.readouterr().out)
    assert summary["exhaustive"] is False
    with gzip.open(tmp_path / summary["violations_artifact"]["file"], "rt") as stream:
        records = [json.loads(line) for line in stream]
    assert len(records) == summary["measurement"]["violation"]
    assert all(codes == sorted(set(codes), key=lambda code: int(code[1:])) and codes for _, codes in records)
    assert not list(tmp_path.glob("*.partial"))
    ordinal = records[0][0]
    monkeypatch.setattr("sys.argv", ["verify", "--ordinal", str(ordinal)])
    main()
    detail = json.loads(capsys.readouterr().out)
    assert detail["violation_codes"] == records[0][1] and detail["primary_violation"] == records[0][1][0]
